import{d as r,C as s,o as g,c as h,a3 as t,E as e,j as a,a as d}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十九章","description":"《正易心法》第二十九章——爻数三百八十又四，以闰求之，其数吻合：384 爻是真天文数，汉儒「六日七分」「除四卦」皆附会；以闰求之则无余欠，三年乾坤气数始足。","frontmatter":{"title":"正易心法·第二十九章","description":"《正易心法》第二十九章——爻数三百八十又四，以闰求之，其数吻合：384 爻是真天文数，汉儒「六日七分」「除四卦」皆附会；以闰求之则无余欠，三年乾坤气数始足。","category":"guide","aliases":["正易心法第二十九章","爻数三百八十四","以闰求之"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-29.md","filePath":"yijing/zheng-yi-xin-fa/chapter-29.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-29.md"},f=r({...c,setup(u){const i=[{id:"z29-01",label:"一、爻数三百八十四",showLabel:!0,sentences:[["爻数三百八十又四，以",{text:"闰",glossary:"run"},"求之，其数吻合。"]],note:["六十四卦的爻数共三百八十四，用闰月来推算，其数自然吻合。（**384 的来源很简单**：64 卦 × 6 爻 = 384 爻。**麻衣要问的是：这个数在天文历法上有没有对应？** 这是汉代以来易学家反复追问的问题。）"]},{id:"z29-02",label:"二、真天文也",showLabel:!0,sentences:[["爻数三百八十又四，",{text:"真天文",glossary:"zhenTianwen"},"也。诸儒求合其数而不可得。"]],note:["爻数三百八十四，是真正的天文之数；历代儒者想要找到与这个数相合的天文依据，却始终找不到。（**「真天文也」四个字是本章的判断前提**：麻衣认为 384 不是偶然的数字游戏，而是天文实数的映现——**问题不在数字，在找法。**）"]},{id:"z29-03",label:"三、汉儒二说皆附会",showLabel:!0,sentences:[["或谓一卦",{text:"六曰七分",glossary:"liuriQifen"},"，或谓除震离坎兑之数，皆",{text:"附会",glossary:"fuhui"},"也。"]],note:["有人说一卦对应「六日七分」，有人说要去掉震离坎兑四卦的爻数（用三百六十爻对应周天三百六十度）——这些都是牵强附会。（**汉儒两法都是「先有结论再凑数」**：前者用 60 卦配 360 天；后者人为剪裁掉四正卦的 24 爻。**麻衣的标准很清楚：如果需要删改数据，那就是附会。**）"]},{id:"z29-04",label:"四、以闰求之无余欠",showLabel:!0,sentences:[["倘以闰求之，则三百八十四数，自然吻合，无余欠矣。盖天度或",{text:"嬴缩",glossary:"yingsuo"},"，至三年，乾坤之气数始足于此也。"]],note:["如果用闰月来推算，那么三百八十四这个数自然吻合，没有多余也没有亏欠。原因在于天体运行有时盈余有时亏缺，到了三年，乾坤的气数才在这里完整足备。（**算法大致是**：太阴历一年约 354 天，太阳历一年约 365 天，年差约 11 天，三年累积约 33 天——正好添一个闰月。**含闰的阴历年因此约 384 天，与 384 爻相应。** 麻衣用「或嬴或缩」解释天度的不均匀，**「至三年，乾坤气数始足」则把这个吻合从「某一年」扩大到了「一个完整周期」。**）"]},{id:"z29-05",label:"五、惟真人得其说",showLabel:!0,sentences:[["由汉以来不悟，惟真人得其说。"]],note:["从汉代以来没有人领悟这个道理，只有真人（麻衣）得到了这个解释。（**这是《正易心法》中罕见的一句「自我宣称」**——前二十八章麻衣几乎从不说「只有我懂」，只批评错误。**但这一章他说「惟真人得其说」**：这句话值得停下来想想。一个人说「只有我懂」，可能是**真的懂了**，也可能是**「以为自己懂了」**。**麻衣的分量在于：他不是标榜，而是指出了一个方向，并且这个方向是可验证的**——三年一闰是历法常识，384 与含闰阴历年的吻合，读者可以自己算。）"]}],l=[{id:"run",term:"闰",pinyin:"rùn",meaning:"闰月、闰年。农历以闰月调整阴阳历差，三年一闰。"},{id:"zhenTianwen",term:"真天文",pinyin:"zhēn tiān wén",meaning:"真正的天文历法之数。麻衣认为 384 是真实的天文数据，非偶然。"},{id:"liuriQifen",term:"六曰七分",pinyin:"liù rì qī fēn",meaning:"汉代卦气说的一种算法：一卦配六日七分（约 6.875 天）。「曰」通「日」。"},{id:"fuhui",term:"附会",pinyin:"fù huì",meaning:"牵强凑合。麻衣批评汉儒：先有结论，再凑数字。"},{id:"yingsuo",term:"嬴缩",pinyin:"yíng suō",meaning:"盈余与亏缺。天度有时多出（嬴）有时不足（缩）——太阳视运动不均匀。"}];return(b,n)=>{const o=s("DaoTextReading"),p=s("DaoKeywordCards");return g(),h("div",null,[n[0]||(n[0]=t("",18)),e(o,{colophon:"三百八十四爻 · 真天文 · 以闰求之 · 无余欠",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十九章原文",sections:i,glossary:l}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文「一卦六曰七分」之「曰」通「日」（六日七分），此处依底本录入、以上文说明，不作径改。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[d("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"真天文",pinyin:["zhēn","tiān"],meaning:"麻衣的判断前提：384 爻不是偶然的数字，而是天文实数的映现——问题不在数字，在找法。"},{term:"六日七分",pinyin:["liù","rì"],meaning:"汉代卦气说：60 卦配 360 天，一卦约六日七分。麻衣判为「附会」。"},{term:"除四卦之数",pinyin:["chú","sì"],meaning:"去掉震离坎兑（四正卦）的 24 爻，得 360 爻配周天——麻衣同样判为附会。"},{term:"以闰求之",pinyin:["yǐ","rùn"],meaning:"含闰的阴历年约 384 天＝384 爻。不是凑合，是自然吻合，故「无余欠」。"},{term:"以天证易",pinyin:["yǐ","tiān"],meaning:"先看天文真实规律，再发现卦数与它的自然吻合——与汉儒「以人合天」（先定结论再凑数）相反。"}]}),n[3]||(n[3]=t("",23))])}}});export{y as __pageData,f as default};
